import shutil
import sqlite3
from dataclasses import dataclass, asdict, field
from pathlib import Path

from agents import function_tool

DB_PATH = "listings.db"
PHOTO_ROOT = Path("/srv/listings/published")


@dataclass
class DeletionResult:
    listing_id: str
    listing_deleted: bool = False
    inquiries_deleted: int = 0
    photos_deleted: bool = False
    errors: list = field(default_factory=list)


@function_tool
def delete_withdrawn_listing(listing_id: str, include_inquiries: bool = True) -> dict:
    result = DeletionResult(listing_id=listing_id)
    conn = sqlite3.connect(DB_PATH)
    try:
        with conn:
            if include_inquiries:
                cur = conn.execute("DELETE FROM inquiries WHERE listing_id = ?", (listing_id,))
                result.inquiries_deleted = cur.rowcount
            cur = conn.execute(
                "DELETE FROM listings WHERE id = ? AND status = 'withdrawn'",
                (listing_id,),
            )
            result.listing_deleted = cur.rowcount > 0
            if not result.listing_deleted:
                raise LookupError("Listing not found or not in withdrawn status")
    except LookupError as exc:
        result.inquiries_deleted = 0
        result.errors.append(str(exc))
        return asdict(result)
    except sqlite3.Error as exc:
        result.errors.append(f"Database error: {exc}")
        return asdict(result)
    finally:
        conn.close()

    photo_dir = PHOTO_ROOT / listing_id
    if photo_dir.exists():
        try:
            shutil.rmtree(photo_dir)
            result.photos_deleted = True
        except OSError as exc:
            result.errors.append(f"Photo removal failed: {exc}")

    return asdict(result)

import sqlite3
from datetime import date

from langchain_core.tools import tool

SHOWINGS_DATABASE_PATH = "listings.db"


@tool
def cancel_open_house_showings(listing_id: str, cancel_from_date: str) -> dict:
    try:
        parsed_cancellation_start_date = date.fromisoformat(cancel_from_date)
    except ValueError:
        return {"listing_id": listing_id, "error": "cancel_from_date must be YYYY-MM-DD"}

    if parsed_cancellation_start_date < date.today():
        return {
            "listing_id": listing_id,
            "error": "Cannot cancel showings that have already taken place",
        }

    showings_database_connection = sqlite3.connect(SHOWINGS_DATABASE_PATH)
    try:
        with showings_database_connection:
            deleted_visitor_signups_cursor = showings_database_connection.execute(
                """
                DELETE FROM open_house_signups
                WHERE showing_id IN (
                    SELECT id FROM open_house_showings
                    WHERE listing_id = ? AND showing_date >= ?
                )
                """,
                (listing_id, parsed_cancellation_start_date.isoformat()),
            )
            number_of_visitor_signups_deleted = deleted_visitor_signups_cursor.rowcount

            deleted_showings_cursor = showings_database_connection.execute(
                "DELETE FROM open_house_showings WHERE listing_id = ? AND showing_date >= ?",
                (listing_id, parsed_cancellation_start_date.isoformat()),
            )
            number_of_showings_canceled = deleted_showings_cursor.rowcount
    except sqlite3.Error as database_error:
        return {"listing_id": listing_id, "error": f"Database error: {database_error}"}
    finally:
        showings_database_connection.close()

    return {
        "listing_id": listing_id,
        "canceled_from": parsed_cancellation_start_date.isoformat(),
        "showings_canceled": number_of_showings_canceled,
        "visitor_signups_removed": number_of_visitor_signups_deleted,
    }
